    ("ShortestCodesV18.nontarget_exists", "{α : Type u} (U : Machine α) (z x : α) (L : Nat) (hL : 0<L) (hx : x≠z) : (∃ p, wrapper U z L p=some x) ↔ ∃ q, U q=some x := @ShortestCodesV18.nontarget_exists α U z x L hL hx"),
