    ("ShortestCodesV18.nontarget_minimum_iff", "{α : Type u} (U : Machine α) (z x : α) (L : Nat) (hL : 0<L) (hx : x≠z) (k : Nat) : MinimumLength (wrapper U z L) x k ↔ ∃ j, k=L+j ∧ MinimumLength U x j := @ShortestCodesV18.nontarget_minimum_iff α U z x L hL hx k"),
