    ("FiniteMarginsV18.score_split", "{n : Nat} (w v : Fin n → Int) (z : Fin n) : score w v=w z*v z+score (without w z) v := @FiniteMarginsV18.score_split n w v z"),
    ("FiniteMarginsV18.without_nonnegative", "{n : Nat} (w : Fin n → Int) (z : Fin n) (hw : ∀ i, 0≤w i) : ∀ i, 0≤without w z i := @FiniteMarginsV18.without_nonnegative n w z hw"),
    ("FiniteMarginsV18.target_window", "{n : Nat} (w v : Fin n → Int) (z : Fin n) (B : Int) (hw : ∀ i, 0≤w i) (hv : ∀ i, 0≤v i ∧ v i≤B) : w z*v z≤score w v ∧ score w v≤w z*v z+B*sum (without w z) := @FiniteMarginsV18.target_window n w v z B hw hv"),
    ("FiniteMarginsV18.strict_separation", "{n : Nat} (w u v : Fin n → Int) (z : Fin n) (B : Int) (hw : ∀ i, 0≤w i) (hu : ∀ i, 0≤u i ∧ u i≤B) (hv : ∀ i, 0≤v i ∧ v i≤B) (hgap : B*sum (without w z)<w z*(v z-u z)) : score w u<score w v := @FiniteMarginsV18.strict_separation n w u v z B hw hu hv hgap"),
