    ("ExpectationContextsV18.expected_monotone", "{α : Type v} [inst : Scalar α] {n : Nat} (w : Probability α n) (f g : Fin n → α) (h : ∀ i, f i≤g i) : expected w f≤expected w g := @ExpectationContextsV18.expected_monotone α inst n w f g h"),
    ("ExpectationContextsV18.expected_constant", "{α : Type v} [inst : Scalar α] {n : Nat} (w : Probability α n) (c : α) : expected w (fun _ => c)=c := @ExpectationContextsV18.expected_constant α inst n w c"),
